+const reloadStatusFilename = "reload-status.json"
+
+// reloadStatus is kept deliberately independent from the metrics describing the
+// last successful configuration load: it describes one complete transactional
+// reload attempt, including a possible rollback.
+type reloadStatus struct {
+	LastReloadID         string             `json:"last_reload_id"`
+	LastReloadSuccessful bool               `json:"last_reload_successful"`
+	ErrorCategory        string             `json:"error_category"`
+	ErrorMessage         string             `json:"error_message"`
+	AppliedReloaders     []string           `json:"applied_reloaders"`
+	RollbackAttempted    bool               `json:"rollback_attempted"`
+	RollbackSuccessful   bool               `json:"rollback_successful"`
+	FailedReloader       string             `json:"failed_reloader"`
+	ReloaderTimingsMS    map[string]float64 `json:"reloader_timings_ms"`
+}
+
+func emptyReloadStatus() reloadStatus {
+	return reloadStatus{ErrorCategory: "none", AppliedReloaders: []string{}, ReloaderTimingsMS: map[string]float64{}}
+}
+
+func (s reloadStatus) apiStatus() api_v1.ReloadStatus {
+	return api_v1.ReloadStatus{
+		LastReloadID: s.LastReloadID, LastReloadSuccessful: s.LastReloadSuccessful,
+		ErrorCategory: s.ErrorCategory, ErrorMessage: s.ErrorMessage,
+		AppliedReloaders: s.AppliedReloaders, RollbackAttempted: s.RollbackAttempted,
+		RollbackSuccessful: s.RollbackSuccessful, FailedReloader: s.FailedReloader,
+		ReloaderTimingsMS: s.ReloaderTimingsMS,
+	}
+}
+
+type transactionalReloadManager struct {
+	filename, statusFile string
+	enableExemplars      bool
+	logger               *slog.Logger
+	noStep               *safePromQLNoStepSubqueryInterval
+	callback             func(bool)
+	reloaders            []reloader
+
+	mu       sync.RWMutex
+	status   reloadStatus
+	lastGood *config.Config
+}
+
+func newTransactionalReloadManager(filename, storageDir string, enableExemplars bool, logger *slog.Logger, noStep *safePromQLNoStepSubqueryInterval, callback func(bool), reloaders []reloader) *transactionalReloadManager {
+	m := &transactionalReloadManager{
+		filename: filename, statusFile: filepath.Join(storageDir, reloadStatusFilename), enableExemplars: enableExemplars,
+		logger: logger, noStep: noStep, callback: callback, reloaders: reloaders, status: emptyReloadStatus(),
+	}
+	data, err := os.ReadFile(m.statusFile)
+	if err == nil {
+		var status reloadStatus
+		if json.Unmarshal(data, &status) == nil && validReloadStatus(status) {
+			if status.AppliedReloaders == nil { status.AppliedReloaders = []string{} }
+			if status.ReloaderTimingsMS == nil { status.ReloaderTimingsMS = map[string]float64{} }
+			m.status = status
+		} else {
+			logger.Warn("Ignoring invalid persisted reload status", "file", m.statusFile, "err", err)
+		}
+	} else if !os.IsNotExist(err) {
+		logger.Warn("Unable to read persisted reload status", "file", m.statusFile, "err", err)
+	}
+	return m
+}
+
+func validReloadStatus(s reloadStatus) bool {
+	switch s.ErrorCategory { case "none", "load_error", "apply_error", "rollback_error": return true }
+	return false
+}
+
+func (m *transactionalReloadManager) Status() api_v1.ReloadStatus {
+	m.mu.RLock()
+	defer m.mu.RUnlock()
+	return m.status.apiStatus()
+}
+
+// InitialLoad establishes the first known-good configuration without recording a
+// reload attempt. It intentionally does not write the status file.
+func (m *transactionalReloadManager) InitialLoad() error { return m.reload(false) }
+func (m *transactionalReloadManager) Reload() error      { return m.reload(true) }
+
+func (m *transactionalReloadManager) reload(record bool) (err error) {
+	start := time.Now()
+	status := emptyReloadStatus()
+	if record { status.LastReloadID = start.UTC().Format(time.RFC3339Nano) }
+	m.logger.Info("Loading configuration file", "filename", m.filename)
+
+	conf, err := config.LoadFile(m.filename, agentMode, m.logger)
+	if err != nil {
+		if record { m.finish(status, false, "load_error", err.Error()) }
+		m.callback(false)
+		return fmt.Errorf("couldn't load configuration (--config.file=%q): %w", m.filename, err)
+	}
+	if m.enableExemplars && conf.StorageConfig.ExemplarsConfig == nil { conf.StorageConfig.ExemplarsConfig = &config.DefaultExemplarsConfig }
+
+	for i, rl := range m.reloaders {
+		rstart := time.Now()
+		err := rl.reloader(conf)
+		status.ReloaderTimingsMS[rl.name] = float64(time.Since(rstart)) / float64(time.Millisecond)
+		if err != nil {
+			status.FailedReloader = rl.name
+			status.ErrorMessage = err.Error()
+			if len(status.AppliedReloaders) > 0 && m.lastGood != nil {
+				status.RollbackAttempted = true
+				status.RollbackSuccessful = true
+				for j := i - 1; j >= 0; j-- {
+					rollbackStart := time.Now()
+					rollbackErr := m.reloaders[j].reloader(m.lastGood)
+					status.ReloaderTimingsMS["rollback_"+m.reloaders[j].name] = float64(time.Since(rollbackStart)) / float64(time.Millisecond)
+					if rollbackErr != nil {
+						status.RollbackSuccessful = false
+						status.ErrorCategory = "rollback_error"
+						status.ErrorMessage = fmt.Sprintf("apply %s: %v; rollback %s: %v", rl.name, err, m.reloaders[j].name, rollbackErr)
+					}
+				}
+			}
+			if status.ErrorCategory == "none" { status.ErrorCategory = "apply_error" }
+			if record { m.finish(status, false, status.ErrorCategory, status.ErrorMessage) }
+			m.callback(false)
+			return fmt.Errorf("failed to apply configuration with reloader %q: %w", rl.name, err)
+		}
+		status.AppliedReloaders = append(status.AppliedReloaders, rl.name)
+	}
+
+	updateGoGC(conf, m.logger)
+	m.noStep.Set(conf.GlobalConfig.EvaluationInterval)
+	m.lastGood = conf
+	m.callback(true)
+	if record { m.finish(status, true, "none", "") }
+	m.logger.Info("Completed loading of configuration file", "filename", m.filename, "totalDuration", time.Since(start))
+	return nil
+}
+
+func (m *transactionalReloadManager) finish(status reloadStatus, successful bool, category, message string) {
+	status.LastReloadSuccessful, status.ErrorCategory, status.ErrorMessage = successful, category, message
+	m.mu.Lock()
+	m.status = status
+	m.mu.Unlock()
+	data, err := json.Marshal(status)
+	if err != nil { m.logger.Error("Unable to marshal reload status", "err", err); return }
+	if err = os.MkdirAll(filepath.Dir(m.statusFile), 0o755); err == nil {
+		tmp := m.statusFile + ".tmp"
+		err = os.WriteFile(tmp, data, 0o644)
+		if err == nil { err = os.Rename(tmp, m.statusFile) }
+	}
+	if err != nil { m.logger.Error("Unable to persist reload status", "file", m.statusFile, "err", err) }
+}
