const reloadStatusFilename = "reload-status.json"

// reloadStatus is kept deliberately independent from the metrics describing the
// last successful configuration load: it describes one complete transactional
// reload attempt, including a possible rollback.
type reloadStatus struct {
	LastReloadID         string             `json:"last_reload_id"`
	LastReloadSuccessful bool               `json:"last_reload_successful"`
	ErrorCategory        string             `json:"error_category"`
	ErrorMessage         string             `json:"error_message"`
	AppliedReloaders     []string           `json:"applied_reloaders"`
	RollbackAttempted    bool               `json:"rollback_attempted"`
	RollbackSuccessful   bool               `json:"rollback_successful"`
	FailedReloader       string             `json:"failed_reloader"`
	ReloaderTimingsMS    map[string]float64 `json:"reloader_timings_ms"`
}

func emptyReloadStatus() reloadStatus {
	return reloadStatus{ErrorCategory: "none", AppliedReloaders: []string{}, ReloaderTimingsMS: map[string]float64{}}
}

func (s reloadStatus) apiStatus() api_v1.ReloadStatus {
	return api_v1.ReloadStatus{
		LastReloadID: s.LastReloadID, LastReloadSuccessful: s.LastReloadSuccessful,
		ErrorCategory: s.ErrorCategory, ErrorMessage: s.ErrorMessage,
		AppliedReloaders: s.AppliedReloaders, RollbackAttempted: s.RollbackAttempted,
		RollbackSuccessful: s.RollbackSuccessful, FailedReloader: s.FailedReloader,
		ReloaderTimingsMS: s.ReloaderTimingsMS,
	}
}

type transactionalReloadManager struct {
	filename, statusFile string
	enableExemplars      bool
	logger               *slog.Logger
	noStep               *safePromQLNoStepSubqueryInterval
	callback             func(bool)
	reloaders            []reloader

	mu       sync.RWMutex
	status   reloadStatus
	lastGood *config.Config
}

func newTransactionalReloadManager(filename, storageDir string, enableExemplars bool, logger *slog.Logger, noStep *safePromQLNoStepSubqueryInterval, callback func(bool), reloaders []reloader) *transactionalReloadManager {
	m := &transactionalReloadManager{
		filename: filename, statusFile: filepath.Join(storageDir, reloadStatusFilename), enableExemplars: enableExemplars,
		logger: logger, noStep: noStep, callback: callback, reloaders: reloaders, status: emptyReloadStatus(),
	}
	data, err := os.ReadFile(m.statusFile)
	if err == nil {
		var status reloadStatus
		if json.Unmarshal(data, &status) == nil && validReloadStatus(status) {
			if status.AppliedReloaders == nil {
				status.AppliedReloaders = []string{}
			}
			if status.ReloaderTimingsMS == nil {
				status.ReloaderTimingsMS = map[string]float64{}
			}
			m.status = status
		} else {
			logger.Warn("Ignoring invalid persisted reload status", "file", m.statusFile)
		}
	} else if !os.IsNotExist(err) {
		logger.Warn("Unable to read persisted reload status", "file", m.statusFile, "err", err)
	}
	return m
}

func validReloadStatus(s reloadStatus) bool {
	switch s.ErrorCategory {
	case "none", "load_error", "apply_error", "rollback_error":
		return true
	}
	return false
}

func (m *transactionalReloadManager) Status() api_v1.ReloadStatus {
	m.mu.RLock()
	defer m.mu.RUnlock()
	return m.status.apiStatus()
}

// InitialLoad establishes the first known-good configuration without recording a
// reload attempt. It intentionally does not write the status file.
func (m *transactionalReloadManager) InitialLoad() error { return m.reload(false) }
func (m *transactionalReloadManager) Reload() error      { return m.reload(true) }

